// Recibe { documento, contenido } y devuelve un item por SUBSECCION del markdown.
//
// Se corta por encabezados de nivel 2 (`## `) y tambien de nivel 3 (`### `). Cortar solo
// por nivel 2 dejaba secciones largas que el troceador partia por caracteres a mitad de
// tema: el fragmento con `pgvector` acababa dentro de otro que empezaba hablando de
// orquestacion, y una pregunta sobre bases de datos vectoriales no lo alcanzaba.
//
// Se lee del Webhook y no de $input porque el nodo anterior (la limpieza en Postgres)
// corre con executeOnce y reemplaza los items por su propio resultado.

const body = $('Webhook Ingesta').first().json.body ?? {};
const documento = String(body.documento || '').trim();
const contenido = String(body.contenido || '');

if (!documento) throw new Error('Falta `documento`: el nombre con el que se identifica el corpus.');
if (contenido.trim().length === 0) throw new Error('Falta `contenido`: el texto del documento.');

const piezas = [];

// Nivel 2 primero.
const porNivel2 = contenido.split(/^##\s+(?!#)/m);
const cabecera = porNivel2.shift();
if (cabecera && cabecera.trim().length > 0) {
  piezas.push({ seccion: 'Introduccion', subseccion: null, texto: cabecera.trim() });
}

for (const bloque of porNivel2) {
  const salto = bloque.indexOf('\n');
  const seccion = (salto === -1 ? bloque : bloque.slice(0, salto)).trim();
  const cuerpo = (salto === -1 ? '' : bloque.slice(salto + 1));

  // Nivel 3 dentro de la seccion.
  const porNivel3 = cuerpo.split(/^###\s+/m);
  const intro = porNivel3.shift();

  if (intro && intro.trim().length > 0) {
    piezas.push({ seccion, subseccion: null, texto: seccion + '\n\n' + intro.trim() });
  }

  for (const sub of porNivel3) {
    const s2 = sub.indexOf('\n');
    const subseccion = (s2 === -1 ? sub : sub.slice(0, s2)).trim();
    const texto = (s2 === -1 ? '' : sub.slice(s2 + 1)).trim();
    if (texto.length === 0) continue;
    // Los titulos se repiten dentro del texto: un fragmento debe poder decir de que
    // habla aunque el troceado lo separe de sus encabezados.
    piezas.push({ seccion, subseccion, texto: seccion + ' — ' + subseccion + '\n\n' + texto });
  }
}

if (piezas.length === 0) throw new Error('El documento no produjo ninguna seccion.');

return piezas.map((p) => ({ json: { documento, seccion: p.seccion, subseccion: p.subseccion ?? '', texto: p.texto } }));

// Deja constancia de cuanto se indexo, que es un criterio del ticket.
const fragmentos = $input.all();
const porSeccion = {};
for (const f of fragmentos) {
  const s = f.json?.metadata?.seccion ?? '(sin seccion)';
  porSeccion[s] = (porSeccion[s] ?? 0) + 1;
}
return [{ json: {
  ok: true,
  documento: $('Partir por seccion').first().json.documento,
  secciones: Object.keys(porSeccion).length,
  fragmentos: fragmentos.length,
  troceado: { chunkSize: 1000, chunkOverlap: 150 },
  modelo_embeddings: 'text-embedding-3-small',
  dimensiones: 1536,
  por_seccion: porSeccion,
} }];

// Devuelve los fragmentos recuperados con su seccion y su distancia,
// para que el gate pueda comprobar de donde salieron y con cuanta conviccion.
const r = $input.all().map((i) => i.json);
return [{ json: {
  pregunta: $('Webhook Buscar').first().json.body.pregunta,
  resultados: r.map((x) => ({
    seccion: x.document?.metadata?.seccion ?? null,
    subseccion: x.document?.metadata?.subseccion || null,
    documento: x.document?.metadata?.documento ?? null,
    distancia: x.score,
    // El fragmento va COMPLETO: recortarlo hacia un gate que busca palabras clave
    // produce fallos falsos cuando la palabra queda mas alla del recorte.
    texto: x.document?.pageContent ?? '',
  })),
} }];
